# Find articulation points
from collections import defaultdict

edges = [(5,13), (8,15), (1,4), (0,4), (8,10), (0,15), (3,10), (7,12), (10,15), (3,7), (4,5), (2,9), (0,9), (3,15), (0,10), (6,9), (3,5), (3,4), (1,14), (6,8), (10,11), (3,14), (4,6), (7,9)]

adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

def is_articulation(v, adj):
    # Check if graph without v is connected
    remaining = [x for x in range(16) if x != v]
    if not remaining:
        return False
    visited = set()
    stack = [remaining[0]]
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            for nb in adj[node]:
                if nb != v and nb not in visited:
                    stack.append(nb)
    return len(visited) != len(remaining)

articulations = []
for v in range(16):
    if is_articulation(v, adj):
        articulations.append(v)
print(f"Articulation points: {articulations}")

# Also check degree-1 vertices - they are always articulation points if graph has > 1 vertex
for v in range(16):
    if len(adj[v]) == 1:
        print(f"Vertex {v} has degree 1")

