from collections import defaultdict

edges = [(5,13), (8,15), (1,4), (0,4), (8,10), (0,15), (3,10), (7,12), (10,15), (3,7), (4,5), (2,9), (0,9), (3,15), (0,10), (6,9), (3,5), (3,4), (1,14), (6,8), (10,11), (3,14), (4,6), (7,9)]
new_edges = [(2,11), (2,12), (11,13), (12,13)]

all_edges = edges + new_edges
print("All edges:", sorted(all_edges))
print("Number of edges:", len(all_edges))

# Verify no articulation points
adj = defaultdict(set)
for u,v in all_edges:
    adj[u].add(v)
    adj[v].add(u)

def is_2_vertex_connected(adj, n=16):
    for v in range(n):
        remaining = [x for x in range(n) if x != v]
        visited = set()
        stack = [remaining[0]]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                for nb in adj[node]:
                    if nb != v and nb not in visited:
                        stack.append(nb)
        if len(visited) != len(remaining):
            print(f"Vertex {v} is an articulation point!")
            return False
    return True

print("Is 2-vertex-connected?", is_2_vertex_connected(adj))

# Also verify all vertices have degree >= 2
for v in range(16):
    if len(adj[v]) < 2:
        print(f"Vertex {v} has degree {len(adj[v])}")
